#!/usr/bin/env bash
# Run the three annotation-free follow-up experiments after VLM caption files
# have been generated by run_vision.sh.  All long LLM/embedding work is
# checkpointed by the Python scripts and can be resumed by re-running this file.
#
# Usage:
#   METRICS_PY=/path/to/venv/bin/python ./run_followup_experiments.sh
#   ./run_followup_experiments.sh --limit 20 --no-meteor
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
RESULTS_DIR="$REPO_ROOT/analysis/results"
LOG_DIR="$REPO_ROOT/analysis/outputs"
METRICS_PY="${METRICS_PY:-python3}"
TRANSLATION_MODEL="${TRANSLATION_MODEL:-ministral-3:14b}"
EMBED_MODEL="${EMBED_MODEL:-qwen3-embedding:4b}"
JUDGE_MODEL="${JUDGE_MODEL:-ministral-3:14b}"
MODELS=("qwen3.8:27b" "gemma4:12b")

LIMIT=0
NO_METEOR=0
SKIP_JUDGE=0
DRY_RUN=0
while [ "$#" -gt 0 ]; do
    case "$1" in
        --limit) LIMIT="$2"; shift 2 ;;
        --no-meteor) NO_METEOR=1; shift ;;
        --skip-judge) SKIP_JUDGE=1; shift ;;
        --dry-run) DRY_RUN=1; shift ;;
        *) echo "Unknown option: $1" >&2; exit 2 ;;
    esac
done

slug() { printf '%s' "$1" | tr -c 'A-Za-z0-9' '_'; }
LIMIT_ARGS=()
[ "$LIMIT" -gt 0 ] && LIMIT_ARGS=(--limit "$LIMIT")
METEOR_ARGS=()
[ "$NO_METEOR" -eq 1 ] && METEOR_ARGS=(--no-meteor)
JUDGE_ARGS=(--judge-model "$JUDGE_MODEL")
[ "$SKIP_JUDGE" -eq 1 ] && JUDGE_ARGS=(--skip-judge)
mkdir -p "$LOG_DIR"

# Reference-style files can always be prepared. Official COCO metrics require
# pycocoevalcap, which is commonly isolated in a separate environment. Do not
# abort the long GPU analysis merely because that optional environment was not
# selected; users can later rerun the metrics stage with METRICS_PY set.
METRICS_ARGS=()
if [ "$DRY_RUN" -eq 1 ] || "$METRICS_PY" -c "import pycocoevalcap" >/dev/null 2>&1; then
    METRICS_ARGS=(--metrics-python "$METRICS_PY" "${METEOR_ARGS[@]}")
else
    echo "WARNING: pycocoevalcap is unavailable in '$METRICS_PY'."
    echo "         Reference-style caption files will be prepared, but COCO metrics will be skipped."
    echo "         Re-run with METRICS_PY=/path/to/capcaption/bin/python to calculate them."
fi

run() {
    local name="$1"; shift
    local log="$LOG_DIR/followup_${name}.log"
    echo "[$(date '+%F %T')] START $name"
    if [ "$DRY_RUN" -eq 1 ]; then
        printf '  '; printf '%q ' "$@"; printf '\n'
        return
    fi
    "$@" 2>&1 | tee "$log"
    echo "[$(date '+%F %T')] DONE  $name"
}

for model in "${MODELS[@]}"; do
    model_slug="$(slug "$model")"
    en="$RESULTS_DIR/vlm_caption__${model_slug}__en.json"
    ar="$RESULTS_DIR/vlm_caption__${model_slug}__ar.json"
    [ -f "$en" ] && [ -f "$ar" ] || {
        echo "Missing VLM captions for $model. Run run_vision.sh first: $en / $ar" >&2
        exit 1
    }
    cross="$RESULTS_DIR/crosslingual_consistency__${model_slug}.json"
    run "crosslingual__${model_slug}" python3 "$SCRIPT_DIR/crosslingual_consistency.py" \
        --english-json "$en" --arabic-json "$ar" \
        --translation-model "$TRANSLATION_MODEL" --embed-model "$EMBED_MODEL" \
        "${JUDGE_ARGS[@]}" "${LIMIT_ARGS[@]}"
    run "reference_style__${model_slug}" python3 "$SCRIPT_DIR/reference_style_sensitivity.py" \
        --crosslingual-json "$cross" "${METRICS_ARGS[@]}"
done

for lang in en ar; do
    qwen="$RESULTS_DIR/vlm_caption__qwen3_8_27b__${lang}.json"
    gemma="$RESULTS_DIR/vlm_caption__gemma4_12b__${lang}.json"
    run "disagreement__${lang}" python3 "$SCRIPT_DIR/vlm_disagreement.py" \
        --captions-a "$qwen" --captions-b "$gemma" --embed-model "$EMBED_MODEL" \
        "${LIMIT_ARGS[@]}"
done

echo "[$(date '+%F %T')] FOLLOW-UP EXPERIMENTS COMPLETE"
